type BlockCardAttrs struct {
	Data       json.RawMessage `json:"data"`
	Datasource json.RawMessage `json:"datasource"`
	Layout     string          `json:"layout,omitempty"` // one of: "wide", "full-width", "center", "wrap-right", "wrap-left", "align-end", "align-start"
	LocalID    string          `json:"localId,omitempty"`
	URL        string          `json:"url,omitempty"`
	Width      *float64        `json:"width,omitempty"`
}

// AsBlockCard types n as a "blockCard" node, decoding its attrs.
func AsBlockCard(n *Node) (*BlockCard, error) {
	if n.Type() != "blockCard" {
		return nil, fmt.Errorf("adf: node is %q, not %q", n.Type(), "blockCard")
	}
	v := &BlockCard{node: n}
	if raw := n.Attrs(); raw != nil {
		if err := json.Unmarshal(raw, &v.Attrs); err != nil {
			return nil, fmt.Errorf("adf: blockCard attrs: %w", err)
		}
	}
	return v, nil
}

// Node returns the underlying substrate node.
func (v *BlockCard) Node() *Node { return v.node }

// NodeType returns NodeTypeBlockCard.
func (v *BlockCard) NodeType() NodeType { return NodeTypeBlockCard }

func (v *BlockCard) typedNode() {}

