// Typed returns the typed view for n, or ErrUnknownNodeType for a
// node type outside the generated catalog.
func Typed(n *Node) (TypedNode, error) {
	switch n.Type() {
	case "blockCard":
		return AsBlockCard(n)
	case "blockTaskItem":
		return AsBlockTaskItem(n)
	case "blockquote":
		return AsBlockquote(n)
	case "bodiedExtension":
		return AsBodiedExtension(n)
	case "bodiedSyncBlock":
		return AsBodiedSyncBlock(n)
	case "bulletList":
		return AsBulletList(n)
	case "caption":
		return AsCaption(n)
	case "codeBlock":
		return AsCodeBlock(n)
	case "date":
		return AsDate(n)
	case "decisionItem":
		return AsDecisionItem(n)
	case "decisionList":
		return AsDecisionList(n)
	case "doc":
		return AsDoc(n)
	case "embedCard":
		return AsEmbedCard(n)
	case "emoji":
		return AsEmoji(n)
	case "expand":
		return AsExpand(n)
	case "extension":
		return AsExtension(n)
	case "hardBreak":
		return AsHardBreak(n)
	case "heading":
		return AsHeading(n)
	case "inlineCard":
		return AsInlineCard(n)
	case "inlineExtension":
		return AsInlineExtension(n)
	case "layoutColumn":
		return AsLayoutColumn(n)
	case "layoutSection":
		return AsLayoutSection(n)
	case "listItem":
		return AsListItem(n)
	case "media":
		return AsMedia(n)
	case "mediaGroup":
		return AsMediaGroup(n)
	case "mediaInline":
		return AsMediaInline(n)
	case "mediaSingle":
		return AsMediaSingle(n)
	case "mention":
		return AsMention(n)
	case "nestedExpand":
		return AsNestedExpand(n)
	case "orderedList":
		return AsOrderedList(n)
	case "panel":
		return AsPanel(n)
	case "paragraph":
		return AsParagraph(n)
	case "placeholder":
		return AsPlaceholder(n)
	case "rule":
		return AsRule(n)
	case "status":
		return AsStatus(n)
	case "syncBlock":
		return AsSyncBlock(n)
	case "table":
		return AsTable(n)
	case "tableCell":
		return AsTableCell(n)
	case "tableHeader":
		return AsTableHeader(n)
	case "tableRow":
		return AsTableRow(n)
	case "taskItem":
		return AsTaskItem(n)
	case "taskList":
		return AsTaskList(n)
	case "text":
		return AsText(n)
	}
	return nil, fmt.Errorf("%w: %q", ErrUnknownNodeType, n.Type())
}

// MarkTyped returns the typed view for m, or ErrUnknownMarkType for
// a mark type outside the generated catalog.
func MarkTyped(m *Mark) (TypedMark, error) {
	switch m.Type() {
	case "alignment":
		return AsAlignmentMark(m)
	case "annotation":
		return AsAnnotationMark(m)
	case "backgroundColor":
		return AsBackgroundColorMark(m)
	case "border":
		return AsBorderMark(m)
	case "breakout":
		return AsBreakoutMark(m)
	case "code":
		return AsCodeMark(m)
	case "dataConsumer":
		return AsDataConsumerMark(m)
	case "em":
		return AsEmMark(m)
	case "fontSize":
		return AsFontSizeMark(m)
	case "fragment":
		return AsFragmentMark(m)
	case "indentation":
		return AsIndentationMark(m)
	case "link":
		return AsLinkMark(m)
	case "strike":
		return AsStrikeMark(m)
	case "strong":
		return AsStrongMark(m)
	case "subsup":
		return AsSubsupMark(m)
	case "textColor":
		return AsTextColorMark(m)
	case "underline":
		return AsUnderlineMark(m)
	}
	return nil, fmt.Errorf("%w: %q", ErrUnknownMarkType, m.Type())
}
